<script setup lang="ts">
import { computed, ref } from 'vue'
type Status = 'Backlog' | 'In progress' | 'Complete'
interface Task { id: number; title: string; status: Status; label: string }
const statuses: Status[] = ['Backlog', 'In progress', 'Complete']
const tasks = ref<Task[]>([{ id: 1, title: 'Sketch a new interface', status: 'Backlog', label: 'DESIGN' }, { id: 2, title: 'Explore a new framework', status: 'Backlog', label: 'RESEARCH' }, { id: 3, title: 'Connect the building blocks', status: 'In progress', label: 'DEVELOPMENT' }, { id: 4, title: 'Launch the playground', status: 'Complete', label: 'MILESTONE' }])
const title = ref(''); const error = ref(''); let nextId = 5
const complete = computed(() => tasks.value.filter(t => t.status === 'Complete').length)
function add() { const value = title.value.trim(); if (!value) { error.value = 'Give your task a name.'; return }; tasks.value.push({ id: nextId++, title: value.slice(0, 100), status: 'Backlog', label: 'PERSONAL' }); title.value = ''; error.value = '' }
function advance(task: Task) { task.status = statuses[(statuses.indexOf(task.status) + 1) % statuses.length]! }
</script>
<template><main><header><div class="logo">◉ ORBIT<span>A LITTLE SPACE TO MAKE THINGS HAPPEN</span></div><span class="badge">VUE 3 / DEMO</span></header><section class="heading"><p class="eyebrow">PERSONAL WORKSPACE</p><h1>Your next mission starts here.</h1><p>Add an idea. Make progress. Close the loop.</p></section><div class="progress-panel"><div><strong>{{ complete }} / {{ tasks.length }}</strong><span>missions complete</span></div><progress :value="complete" :max="Math.max(tasks.length, 1)" aria-label="Completed tasks" /></div><form @submit.prevent="add"><input v-model="title" maxlength="100" aria-label="New task title" placeholder="What are we building next?" :aria-invalid="!!error" aria-describedby="task-error" /><button type="submit">+ Add mission</button></form><p v-if="error" id="task-error" role="alert" class="error">{{ error }}</p><div class="board"><section v-for="status in statuses" :key="status" class="column"><h2><span :class="['dot', { done: status === 'Complete' }]" />{{ status }}<small>{{ tasks.filter(t => t.status === status).length }}</small></h2><article v-for="task in tasks.filter(t => t.status === status)" :key="task.id"><span class="tag">{{ task.label }}</span><button class="remove" :aria-label="`Delete ${task.title}`" @click="tasks = tasks.filter(t => t.id !== task.id)">×</button><h3>{{ task.title }}</h3><div><small>ORB-{{ String(task.id).padStart(3, '0') }}</small><button class="advance" :aria-label="`Move ${task.title} to ${statuses[(statuses.indexOf(task.status) + 1) % statuses.length]}`" @click="advance(task)">{{ status === 'Complete' ? '↺ Reopen' : 'Next →' }}</button></div></article><p v-if="!tasks.some(t => t.status === status)" class="empty">A little room for your next idea.</p></section></div><footer>DEMONSTRATION DATA / IN-MEMORY SESSION — REFRESH TO RESET<br>BUILT WITH VUE 3 + TYPESCRIPT</footer></main></template>
